def spans(closes):
    out = []
    stack = []  # indices of earlier closes, falling
    for i, c in enumerate(closes):
        while stack and closes[stack[-1]] <= c:
            stack.pop()
        out.append(i + 1 if not stack else i - stack[-1])
        stack.append(i)
    return out

def first_over_cap(n, updates, cap):
    def over(k):  # does some day exceed cap after the first k updates?
        d = [0] * (n + 1)
        for l, r, v in updates[:k]:
            d[l] += v
            d[r + 1] -= v
        run = 0
        for i in range(n):
            run += d[i]
            if run > cap:
                return True
        return False

    if not over(len(updates)):
        return -1
    lo, hi = 1, len(updates)
    while lo < hi:
        mid = (lo + hi) // 2
        if over(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo
